  },
  {
   "id": "cd-420458-cb-20261024-104722-ivw-f12",
   "statement": "The pickup place said it will not hand over the Ferrari until the seller's signed release has arrived at that address and the hold is lifted.",
   "source": "pickup_place: Calverona Hamburg, Lukas Brandt (workshop)",
   "channel": "call",
   "at": "2026-10-21T09:27:47.847Z",
   "strength": "stated"
  },
  {
